{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Ensure that Cloud SQL database Instances are not open to the world",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The database instance allows connections from 0.0.0.0/0, which exposes it to the entire internet. This increases the risk of unauthorized access."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The 'require_ssl' setting is set to false, which allows unencrypted connections to the database. This can lead to data interception."
    },
    {
      "check_id": "CKV_GCP_60",
      "title": "Ensure Cloud SQL database does not have public IP",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The 'ipv4_enabled' setting is true, which enables a public IP for the database. This increases the attack surface."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Ensure PostgreSQL database 'log_checkpoints' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_checkpoints' flag is not explicitly set to 'on', which can hinder troubleshooting and performance analysis."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "Ensure PostgreSQL database 'log_connections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_connections' flag is not explicitly set to 'on', which can hinder auditing of connection activity."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Ensure PostgreSQL database 'log_disconnections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_disconnections' flag is not explicitly set to 'on', which can hinder auditing of disconnection activity."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is not explicitly set to 'on', which can hinder troubleshooting of lock contention issues."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "Ensure PostgreSQL database flag 'log_duration' is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_duration' flag is not explicitly set to 'on', which can hinder performance analysis by not logging query durations."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = false\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n  }\n  deletion_protection = false\n}",
  "fix_summary": "Removed public IP exposure by setting 'ipv4_enabled' to false and removed the 0.0.0.0/0 authorized network. Enabled SSL by setting 'require_ssl' to true. Added database flags for 'log_checkpoints', 'log_connections', 'log_disconnections', 'log_lock_waits', and 'log_duration' to enhance observability and logging."
}
